// Obtener productos con stock bajo del nodo anterior
const lowStockProducts = $('Get Low Stock Products').all();
const adminPhone = $('Get Admin WhatsApp').first().json.admin_whatsapp;

// Crear mensaje formateado
let message = '🚨 *ALERTA DE STOCK BAJO* 🚨\n\n';
message += `📅 Fecha: ${new Date().toLocaleDateString('es-ES')}\n`;
message += `⏰ Hora: ${new Date().toLocaleTimeString('es-ES')}\n\n`;
message += `Se encontraron *${lowStockProducts.length}* productos con stock bajo:\n\n`;

lowStockProducts.forEach((item, index) => {
  const product = item.json;
  message += `${index + 1}. *${product.name}*\n`;
  message += `   📦 Stock actual: ${product.stock}\n`;
  message += `   📁 Categoría: ${product.category_name || 'Sin categoría'}\n`;
  message += `   ⚠️ Mínimo requerido: ${product.min_stock_alert}\n\n`;
});

message += '---\n';
message += '_Por favor, reponer inventario lo antes posible._';

return {
  phone: adminPhone,
  message: message,
  productCount: lowStockProducts.length
};
